1	package credit
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"reflect"
8		"strings"
9		"unicode/utf8"
10	)
11	
12	// duplicateFieldError 表示同一个 JSON 对象内出现了读取功能无法确定归属的
13	// 两个字段：
14	//   - 字段名完全相同（first == second，如两份 "credit"）；
15	//   - 两个字段名只有大小写差异（编码/json 的大小写折叠等同于
16	//     strings.EqualFold），却都被现有读取功能识别为同一条记录字段
17	//     （如 "credit" 与 "Credit" 都填入课程学分，"courses" 与
18	//     "COURSES" 都填入最外层课程列表）。
19	//
20	// field 是两者共同指向的规范字段名（结构体 json 标签原文）；完全同名时
21	// 与 first、second 相同。
22	type duplicateFieldError struct {
23		field  string
24		first  string
25		second string
26	}
27	
28	func (e *duplicateFieldError) Error() string {
29		if e.first == e.second {
30			return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.first)
31		}
32		return fmt.Sprintf(
33			"同一 JSON 对象内字段名 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定",
34			e.first, e.second, e.field)
35	}
36	
37	// nullCourseOpenError 表示某条课程记录显式提供了开放状态字段，却把值写成
38	// JSON 的 null（"open":null，大小写与 Unicode 转义变体同理）。课程编号、
39	// 名称与学分合法也不能放过：标准库把 null 解进非指针 bool 时不报错、字段
40	// 保持零值 false，于是“状态未确定”的记录被悄悄读成“停开”，课程列表显示
41	// 停开、新增修读被误拒，之后任何一次保存还会把未定状态写成明确的 false。
42	// 这属于记录内容损坏，必须拒绝整份文件，而不是跳过该课程继续办理。
43	//
44	// courseID 是该课程对象内 id 字段解码后的编号（字段位置不影响判定，编号
45	// 出现在开放状态之后也能取到；课程确实没有编号时为空串）；key 是开放状态
46	// 字段的原始写法（解码后文字），用于说明是哪一种写法被写成了 null。
47	type nullCourseOpenError struct {
48		courseID string
49		key      string
50	}
51	
52	func (e *nullCourseOpenError) Error() string {
53		id := e.courseID
54		if id == "" {
55			id = "（该课程记录未提供编号）"
56		}
57		return fmt.Sprintf(
58			"课程 %s 的课程开放状态为空：字段 %q 被显式写成 null，开放状态只能是 true（开放）或 false（停开）",
59			id, e.key)
60	}
61	
62	// objKind 标识一个 JSON 对象在记录格式中的位置，用于确定该对象有哪些
63	// “能被现有读取功能识别”的字段名。
64	type objKind int
65	
66	const (
67		objUnknown     objKind = iota // 不属于记录格式的对象（交由结构体解码按未知字段/类型拒绝）
68		objFile                       // 记录最外层 fileData
69		objCourse                     // courses 数组元素：课程
70		objStudent                    // students 数组元素：学生
71		objRequirement                // requirements 数组元素：课程要求
72		objEnrollment                 // enrollments 数组元素：修读
73		objWaiver                     // waivers 数组元素：免修
74	)
75	
76	// recordObjectTypes 把每类对象对应到它在记录格式中的结构体类型。各类对象
77	// “能被读取功能识别哪些字段名”只有结构体定义上的 json 标签这一个出处：
78	// 正常读取时 json.Decoder 按这些标签（先精确名、再大小写折叠名）填入字段，
79	// 字段重复扫描与课程开放状态扫描也从同一份结构体定义取字段名。调整一项
80	// 记录的字段（增删、改名、换标签）只需改结构体定义，正常读取与两项扫描
81	// 始终对“哪些字段可识别、哪些写法指向同一字段、键下是不是课程对象”作出
82	// 一致判断，不需要再同步另一份字段名称清单。
83	var recordObjectTypes = map[objKind]reflect.Type{
84		objFile:        reflect.TypeOf(fileData{}),
85		objCourse:      reflect.TypeOf(Course{}),
86		objStudent:     reflect.TypeOf(Student{}),
87		objRequirement: reflect.TypeOf(Requirement{}),
88		objEnrollment:  reflect.TypeOf(Enrollment{}),
89		objWaiver:      reflect.TypeOf(Waiver{}),
90	}
91	
92	// jsonFieldName 按 encoding/json 的规则给出结构体字段被识别的 JSON 名称：
93	// 未导出字段不参与解码；json 标签为 "-" 的字段跳过（返回空串）；没有标签
94	// 时用 Go 字段名本身；omitempty 等选项不影响名称。记录结构体均为扁平字段，
95	// 无嵌入字段提升问题。
96	func jsonFieldName(sf reflect.StructField) string {
97		if sf.PkgPath != "" {
98			return ""
99		}
100		name := sf.Tag.Get("json")
101		if name == "-" {
102			return ""
103		}
104		if comma := strings.IndexByte(name, ','); comma >= 0 {
105			name = name[:comma]
106		}
107		if name == "" {
108			name = sf.Name
109		}
110		return name
111	}
112	
113	// recordFields 是各类对象能被读取功能识别的字段名（结构体 json 标签原文），
114	// 全部直接取自 recordObjectTypes 中的结构体定义，不在别处另列一份。
115	// 同一对象的字段名在大小写不敏感比较下必须两两不同——否则该格式本身就有
116	// 歧义（两个字段折叠到同一名称），在初始化阶段直接指出这类定义错误。
117	var recordFields = buildRecordFields()
118	
119	func buildRecordFields() map[objKind][]string {
120		m := make(map[objKind][]string, len(recordObjectTypes))
121		for kind, t := range recordObjectTypes {
122			names := make([]string, 0, t.NumField())
123			for i := 0; i < t.NumField(); i++ {
124				name := jsonFieldName(t.Field(i))
125				if name == "" {
126					continue
127				}
128				for _, other := range names {
129					if strings.EqualFold(name, other) {
130						panic(fmt.Sprintf(
131							"记录结构体 %s 的字段 %q 与 %q 在大小写折叠后同名，记录格式存在歧义",
132							t.Name(), name, other))
133					}
134				}
135				names = append(names, name)
136			}
137			m[kind] = names
138		}
139		return m
140	}
141	
142	// matchRecordField 报告键名 key 是否会被现有读取功能填入 kind 对象的某个
143	// 记录字段，命中时返回该字段的规范名称（json 标签原文）。
144	//
145	// encoding/json 解进结构体时先按精确名匹配，不中再按大小写折叠名匹配，
146	// 折叠规则等同于 strings.EqualFold（完整 Unicode 简单折叠，而非仅 ASCII：
147	// 例如 U+212A“K”折到 k、U+0130“İ”折到 i）。这里照搬同一判定，字段名又
148	// 直接来自结构体标签，才能保证“两个键名被现有读取功能识别为同一字段”的
149	// 口径与实际解码完全一致——任何大小写或 Unicode 转义组合都无法让一个键
150	// 绕过本扫描却仍被解码器接受。字段归属唯一性检查与课程开放状态检查都经
151	// 由这同一个入口识别字段，两者口径始终相同。
152	func matchRecordField(kind objKind, key string) (string, bool) {
153		for _, tag := range recordFields[kind] {
154			if strings.EqualFold(key, tag) {
155				return tag, true
156			}
157		}
158		return "", false
159	}
160	
161	// fileKeyObjectKind 给出最外层对象某个键所对应数组元素/嵌套对象的类型。
162	// 记录格式里只有最外层的五个数组承载记录对象。归属同样直接由 fileData 的
163	// 结构体定义推导：键按大小写折叠命中哪个字段，就取该字段（切片取元素、
164	// 指针解引用）的类型再反查对象类型——courses 与 COURSES 解出来都是课程
165	// 列表，其元素必须按课程对象检查，不能借顶层键的大小写写法绕过限制；
166	// version 等非记录对象字段返回 objUnknown。
167	func fileKeyObjectKind(key string) objKind {
168		t := recordObjectTypes[objFile]
169		for i := 0; i < t.NumField(); i++ {
170			sf := t.Field(i)
171			name := jsonFieldName(sf)
172			if name == "" || !strings.EqualFold(name, key) {
173				continue
174			}
175			ft := sf.Type
176			if ft.Kind() == reflect.Slice {
177				ft = ft.Elem()
178			}
179			if ft.Kind() == reflect.Ptr {
180				ft = ft.Elem()
181			}
182			for kind, rt := range recordObjectTypes {
183				if rt == ft {
184					return kind
185				}
186			}
187			return objUnknown
188		}
189		return objUnknown
190	}
191	
192	// recordTokenHooks 是 walkFirstRecordValue 向具体检查开放的时机。
193	// 字段归属检查与课程开放状态检查只提供各自的“发现规则”，不再各自处理
194	// 对象与数组的层次、记录类别推导，以及键与字符串值的区分——这些共通规则
195	// 全部集中在遍历器一处维护。
196	//
197	// 回调拿到的 kind/key 都由遍历器按记录结构推导：
198	//   - objectStart 在每个对象（含根对象）压栈后调用一次，kind 是该对象在
199	//     记录格式中的类别（objUnknown 表示不属于记录格式的对象）；
200	//   - key 在对象内读到键时调用，key 是 JSON 解码后的键名原文（\uXXXX
201	//     转义已还原），与正常解码时看到的写法不可区分；
202	//   - stringValue 在读到字符串“值”（不是键）时调用，key 是其所属键的
203	//     原文，value 是解码后的文字；
204	//   - scalarValue 在读到其余标量值（number、bool、null）时调用，key 是
205	//     其所属键的原文；tok 为无类型 nil 时即 JSON null——字符串字面量
206	//     "null" 走 stringValue，绝不会以 nil 出现，名称、依据里的“null”
207	//     文字因此天然不被当成空值；
208	//   - objectEnd 在对象的 '}' 读到、结构帧出栈之前调用，便于检查汇总整个
209	//     对象（如课程编号出现在问题字段之后，仍能在对象闭合时点名课程）。
210	//
211	// 数组本身不产生回调；数组各元素对象照常成对触发 objectStart/objectEnd。
212	// 任一带返回值的回调返回非 nil 错误时，遍历立即中止并原样返回该错误。
213	type recordTokenHooks struct {
214		objectStart func(kind objKind)
215		key         func(kind objKind, key string) error
216		stringValue func(kind objKind, key, value string) error
217		scalarValue func(kind objKind, key string, tok any) error
218		objectEnd   func(kind objKind) error
219	}
220	
221	// walkFirstRecordValue 遍历第一份完整 JSON 值的 token 流：按记录结构维护
222	// 对象/数组栈，把“对象起止、键、标量值”四个时机交给 hooks。第一份值之后
223	// 的字节一律不读——调用方另行检查完整记录之后是否拼接了多余内容，那里的
224	// 报错信息必须与本遍历中的检查区分开。
225	//
226	// 对象类别与正常解码同一出处（见 fileKeyObjectKind）：根对象是最外层
227	// fileData；对象直接挂在最外层对象的某个键下时，类别由该键按大小写折叠
228	// 推导（courses 与 COURSES 之下都是课程对象）；对象在数组里时类别跟随
229	// 承载它的数组，数组嵌套则逐层沿用——顶层键的大小写写法与数组嵌套都不能
230	// 改变元素对象被识别成的记录类别，两项检查由此始终按同一口径识别课程
231	// 记录。
232	//
233	// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），遍历器据此
234	// 区分字符串 token 是键还是字符串值；嵌套对象/数组整体结束时也算外层键
235	// 对应的值读完。限制只针对同一对象：每个对象独立成帧，数组各元素、不同
236	// 课程或不同学生互不比较。
237	//
238	// 语法残缺（未闭合、值缺失等）不在本遍历的报错范围：returnSyntaxErr 为
239	// false 时一律按“未发现本检查的问题”返回 nil，语法问题留给调用方随后的
240	// 结构体解码阶段报告；为 true 时把 json.Decoder 的语法错误原样返回（调用
241	// 方同样只从中识别自己的检查错误，其余仍交给解码阶段）。io.EOF（含空
242	// 输入）两种模式下都返回 nil。
243	func walkFirstRecordValue(r io.Reader, returnSyntaxErr bool, hooks recordTokenHooks) error {
244		type frame struct {
245			isObj bool
246			// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
247			kind objKind
248			// elem 标识数组元素对象的类型（数组帧使用）。
249			elem objKind
250			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
251			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。对象内
252			// token 天然按键、值、键、值交替（逗号不产生 token），借此区分
253			// 字符串 token 是键还是普通字符串值。
254			expectKey bool
255			// pendingKey 是当前值所属的键（解码后文字），用于判断嵌套对象/
256			// 数组的类型，并随标量值回调交给具体检查。
257			pendingKey string
258		}
259		var stack []frame
260		depth := 0
261	
262		push := func(d json.Delim) {
263			switch d {
264			case '{':
265				kind := objUnknown
266				if n := len(stack); n == 0 {
267					// 第一份值的根对象即记录最外层；根值不是对象时结构体
268					// 解码阶段自会按类型拒绝。
269					kind = objFile
270				} else if p := &stack[n-1]; p.isObj {
271					if p.kind == objFile {
272						kind = fileKeyObjectKind(p.pendingKey)
273					}
274				} else {
275					// 对象在数组里：类型由承载它的数组决定（数组类型又由
276					// 最外层五个字段之一决定）。
277					kind = stack[n-1].elem
278				}
279				stack = append(stack, frame{isObj: true, kind: kind, expectKey: true})
280				if hooks.objectStart != nil {
281					hooks.objectStart(kind)
282				}
283			case '[':
284				elem := objUnknown
285				if n := len(stack); n > 0 {
286					if p := &stack[n-1]; p.isObj {
287						if p.kind == objFile {
288							elem = fileKeyObjectKind(p.pendingKey)
289						}
290					} else {
291						// 数组嵌套：内层数组元素类型跟随外层数组。
292						elem = p.elem
293					}
294				}
295				stack = append(stack, frame{isObj: false, elem: elem})
296			}
297		}
298		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
299		valueEnded := func() {
300			if n := len(stack); n > 0 {
301				f := &stack[n-1]
302				if f.isObj && !f.expectKey {
303					f.expectKey = true
304					f.pendingKey = ""
305				}
306			}
307		}
308	
309		dec := json.NewDecoder(r)
310		for {
311			tok, err := dec.Token()
312			if err == io.EOF {
313				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
314				return nil
315			}
316			if err != nil {
317				if returnSyntaxErr {
318					return err
319				}
320				// 语法问题留给随后的结构体解码报告；本检查只负责自己的发现。
321				return nil
322			}
323			switch t := tok.(type) {
324			case json.Delim:
325				switch t {
326				case '{', '[':
327					depth++
328					push(t)
329				case '}', ']':
330					depth--
331					cur := stack[len(stack)-1]
332					if t == '}' && hooks.objectEnd != nil {
333						// 出栈前汇总：课程编号等对象内信息此刻无论先后都已
334						// 到齐。
335						if err := hooks.objectEnd(cur.kind); err != nil {
336							return err
337						}
338					}
339					stack = stack[:len(stack)-1]
340					if depth == 0 {
341						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
342						return nil
343					}
344					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
345					valueEnded()
346				}
347			case string:
348				n := len(stack)
349				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
350					f := &stack[n-1]
351					if hooks.key != nil {
352						if err := hooks.key(f.kind, t); err != nil {
353							return err
354						}
355					}
356					f.expectKey = false
357					f.pendingKey = t
358					continue
359				}
360				// 字符串值：名称、依据等普通文字在这里出现，包括字面写出的
361				// "null" 与字段名，都只是文字。
362				if n > 0 && stack[n-1].isObj {
363					f := &stack[n-1]
364					if hooks.stringValue != nil {
365						if err := hooks.stringValue(f.kind, f.pendingKey, t); err != nil {
366							return err
367						}
368					}
369					valueEnded()
370				}
371				if depth == 0 {
372					return nil // 顶层标量值
373				}
374			default:
375				// number、bool 等标量值；JSON null 的 token 是无类型 nil。
376				if n := len(stack); n > 0 && stack[n-1].isObj {
377					f := &stack[n-1]
378					if hooks.scalarValue != nil {
379						if err := hooks.scalarValue(f.kind, f.pendingKey, tok); err != nil {
380							return err
381						}
382					}
383					valueEnded()
384				}
385				if depth == 0 {
386					return nil
387				}
388			}
389		}
390	}
391	
392	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
393	// 字段归属唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后
394	// 是否还拼接了多余内容，那里的报错信息需要与本检查区分开）。
395	//
396	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
397	// 后一个静默覆盖，而且结构体字段按大小写折叠匹配 json 标签（规则等同于
398	// strings.EqualFold）——同一门课程同时写 "credit":4 与 "Credit":9 时，
399	// 标准库读不出“曾经写过两个”，学分直接被后一个值顶替，两个键先后颠倒
400	// 结果也随之颠倒。因此在正常结构体解码之前先单独扫描一遍 token 流。
401	//
402	// 检查只保留自己的发现规则，层次与类别推导全部复用 walkFirstRecordValue：
403	//   - 同一个 JSON 对象内字段归属只能确定一次：完全同名的两个键，或两个
404	//     键名在大小写折叠后都指向同一条可识别记录字段（如 credit 与
405	//     Credit、student 与 Student、courses 与 COURSES），发现即返回
406	//     *duplicateFieldError（含规范字段名与两个原始写法）。
407	//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
408	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
409	//     反转义，所以 "credit"、它的 \uXXXX 转义写法与 "Credit" 之间任意
410	//     的两两组合都按解码后实际所指的字段判断，不能用转义加大小写的组合
411	//     绕开限制。
412	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
413	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
414	//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
415	//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
416	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
417	func scanDuplicateKeys(r io.Reader) error {
418		type dupState struct {
419			// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
420			rawKeys map[string]struct{}
421			// seen 记录每条可识别记录字段第一次出现时的原始写法，以规范
422			// 字段名为索引；无法识别的键不进此表。
423			seen map[string]string
424		}
425		// 每个对象一份状态，随遍历器的 objectStart/objectEnd 成对压退，天然
426		// 只在同一对象内比较；数组不压状态，元素对象各自独立。
427		var states []dupState
428	
429		hooks := recordTokenHooks{
430			objectStart: func(objKind) {
431				states = append(states, dupState{
432					rawKeys: map[string]struct{}{},
433					seen:    map[string]string{},
434				})
435			},
436			objectEnd: func(objKind) error {
437				states = states[:len(states)-1]
438				return nil
439			},
440			key: func(kind objKind, key string) error {
441				st := &states[len(states)-1]
442				// 对象键：Token() 已按解码后的文字返回，\uXXXX 转义形式的
443				// 键名与直接写出的同名键在这里完全不可区分。
444				if _, dup := st.rawKeys[key]; dup {
445					return &duplicateFieldError{field: key, first: key, second: key}
446				}
447				st.rawKeys[key] = struct{}{}
448				// 只有指向同一条可识别记录字段的不同写法才算归属冲突；
449				// 未知键的大小写变体随后由结构体解码按未知字段拒绝（如
450				// "foo" 与 "Foo" 不会被当成任何业务字段）。
451				if canonical, known := matchRecordField(kind, key); known {
452					if prev, conflict := st.seen[canonical]; conflict {
453						return &duplicateFieldError{
454							field:  canonical,
455							first:  prev,
456							second: key,
457						}
458					}
459					st.seen[canonical] = key
460				}
461				return nil
462			},
463		}
464		// 语法残缺由遍历器原样返回 json.Decoder 错误；Load 只按
465		// *duplicateFieldError 识别本检查的发现，其余错误仍交给解码阶段。
466		return walkFirstRecordValue(r, true, hooks)
467	}
468	
469	// scanNullCourseOpen 扫描第一份完整 JSON 值的 token 流：只要某个课程对象
470	// （courses 数组元素，含最外层键的大小写变体与数组嵌套）显式给出开放状态
471	// 字段且值是 JSON null，就返回 *nullCourseOpenError。
472	//
473	// 与 scanDuplicateKeys 共用同一遍历与字段识别口径（见
474	// walkFirstRecordValue 与 matchRecordField），今后调整记录结构时两项检查
475	// 仍按同一口径识别课程记录：
476	//   - 键名以 JSON 解码后的文字按 strings.EqualFold 与课程结构体的 open
477	//     标签比较，open、Open、OPEN 以及解码后等同于这些写法的 \uXXXX 转义
478	//     都指向同一状态字段，字段在课程对象中的位置不影响结果；
479	//   - 只认“键后紧跟的值 token 就是 nil（JSON null）”这一种情形：字符串
480	//     字面量 "null" 走字符串值回调，是普通文字，课程名称、免修依据里出现
481	//     它不算状态空值；开放状态写成对象/数组等其他类型留给结构体解码按
482	//     类型错误拒绝。
483	//
484	// 课程对象之外的 null 不由本检查处理：最外层的 null 或空数组继续按既有
485	// 读取规则判读（顶层 null/数组本来就不是合法记录），"courses":null 这类
486	// 空列表照常按没有课程读取。报错推迟到该课程对象完整读完时（objectEnd）
487	// 发出，这样无论 id 字段出现在开放状态之前还是之后，错误都能点名课程
488	// 编号。
489	func scanNullCourseOpen(r io.Reader) error {
490		type openState struct {
491			// courseID 记录本课程对象已读到的编号，供报错时点名。
492			courseID string
493			// openNullKey 记录开放状态被写成 null 时该字段的原始写法；
494			// 非空表示本课程对象已构成损坏。
495			openNullKey string
496		}
497		// 每个对象一份状态，随遍历器的 objectStart/objectEnd 成对压退；只有
498		// 课程对象会写入其中字段。
499		var states []openState
500	
501		hooks := recordTokenHooks{
502			objectStart: func(objKind) {
503				states = append(states, openState{})
504			},
505			objectEnd: func(kind objKind) error {
506				st := &states[len(states)-1]
507				var err error
508				if kind == objCourse && st.openNullKey != "" {
509					// 课程对象已完整读完，id 无论先后都已记录在案。
510					err = &nullCourseOpenError{courseID: st.courseID, key: st.openNullKey}
511				}
512				states = states[:len(states)-1]
513				return err
514			},
515			stringValue: func(kind objKind, key, value string) error {
516				// 字符串值：在课程对象内顺带记录编号；普通文字 "null" 走的
517				// 也是这里，绝不会被当成开放状态空值。
518				if kind == objCourse {
519					if canonical, ok := matchRecordField(objCourse, key); ok && canonical == "id" {
520						states[len(states)-1].courseID = value
521					}
522				}
523				return nil
524			},
525			scalarValue: func(kind objKind, key string, tok any) error {
526				if kind == objCourse && tok == nil {
527					if canonical, ok := matchRecordField(objCourse, key); ok && canonical == "open" {
528						st := &states[len(states)-1]
529						// 只记第一处；整份文件都会被拒绝，列出哪一门都成立。
530						if st.openNullKey == "" {
531							st.openNullKey = key
532						}
533					}
534				}
535				return nil
536			},
537		}
538		// 语法问题留给随后的结构体解码报告；本检查只负责发现 null 状态。
539		return walkFirstRecordValue(r, false, hooks)
540	}
541	
542	// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
543	// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
544	//   - 字符串中直接写入的字节必须是合法 UTF-8；
545	//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
546	//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
547	//
548	// 背景：encoding/json 解码时会把非法 UTF-8 字节与未配对的代理项转义静默
549	// 替换成 U+FFFD（“�”）。替换后的学生编号、课程名称或免修依据绝不能被当成
550	// 正常内容继续查询、核对或登记——两个本来不同的编号可能被替换成同一个
551	// 而被误判重复或误判相同。因此必须在结构体解码之前按原始字节拒绝这样的
552	// 文件，整份判为内容损坏，哪怕问题只出现在一条已拒绝免修的依据里、或在与
553	// 本次核对无关的课程名称里。
554	//
555	// 合法文字不受影响：中文、直接写入的补充平面字符、完整的高低代理项转义对、
556	// 用转义表达的控制字符都保留原意；用户确实写入的“�”（U+FFFD，直接写出
557	// 或 \uFFFD 转义）也是合法文字，不能仅因解码结果含有它就拒绝文件。
558	//
559	// 与 scanDuplicateKeys 一样只扫描第一份完整值：完整记录之后的多余内容
560	// 本来就会被读取方拒绝，无需在此重复判定。
561	func scanStringUnicode(raw []byte) error {
562		i := 0
563		for i < len(raw) && isJSONSpace(raw[i]) {
564			i++
565		}
566		if i >= len(raw) {
567			return nil // 空输入交由后续结构体解码报错
568		}
569		switch raw[i] {
570		case '"':
571			// 顶层就是一个字符串：扫描它本身即可。
572			_, err := scanJSONString(raw, i)
573			return err
574		case '{', '[':
575		default:
576			return nil // 顶层标量（数字、true、false、null）不含字符串
577		}
578		depth := 0
579		for i < len(raw) {
580			switch raw[i] {
581			case '"':
582				j, err := scanJSONString(raw, i)
583				if err != nil {
584					return err
585				}
586				i = j
587			case '{', '[':
588				depth++
589				i++
590			case '}', ']':
591				depth--
592				i++
593				if depth == 0 {
594					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
595					return nil
596				}
597			default:
598				i++
599			}
600		}
601		return nil // 未闭合的结构由 JSON 解析报错
602	}
603	
604	// scanJSONString 扫描从 raw[start]（必须是 '"'）开始的一个字符串字面量，
605	// 返回结束引号之后的下标。字符串内容无法还原为合法 Unicode 文字时报错；
606	// 未闭合、非法转义形式等语法问题留给 JSON 解析器报告，本函数不为此报错。
607	func scanJSONString(raw []byte, start int) (int, error) {
608		i := start + 1
609		for i < len(raw) {
610			c := raw[i]
611			switch {
612			case c == '"':
613				return i + 1, nil
614			case c == '\\':
615				if i+1 >= len(raw) {
616					return len(raw), nil
617				}
618				if raw[i+1] != 'u' {
619					i += 2 // 其他转义的合法性由 JSON 解析器校验
620					continue
621				}
622				v, ok := hex4(raw, i+2)
623				if !ok {
624					i += 2 // 非法 \u 转义形式由 JSON 解析器报错
625					continue
626				}
627				switch {
628				case isHighSurrogate(v):
629					// 高位代理项必须紧跟一个 \uXXXX 形式的低位代理项转义。
630					if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
631						if v2, ok := hex4(raw, i+8); ok && isLowSurrogate(v2) {
632							i += 12
633							continue
634						}
635					}
636					return 0, fmt.Errorf(
637						`高位代理项转义 \u%04X 后没有紧跟低位代理项转义`, v)
638				case isLowSurrogate(v):
639					return 0, fmt.Errorf(
640						`低位代理项转义 \u%04X 没有对应的高位代理项转义`, v)
641				default:
642					i += 6
643				}
644			case c < utf8.RuneSelf:
645				i++
646			default:
647				// 直接写入的多字节字符必须是合法 UTF-8。注意 U+FFFD 本身
648				// 是合法文字：只有解码失败（size 为 1）才拒绝。
649				r, size := utf8.DecodeRune(raw[i:])
650				if r == utf8.RuneError && size == 1 {
651					return 0, fmt.Errorf(
652						"字符串中直接写入的字节 0x%02X 不是合法 UTF-8", c)
653				}
654				i += size
655			}
656		}
657		return i, nil // 未闭合的字符串由 JSON 解析器报错
658	}
659	
660	func isJSONSpace(c byte) bool {
661		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
662	}
663	
664	func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
665	func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }
666	
667	// hex4 把 b[i:i+4] 读作四位十六进制数。
668	func hex4(b []byte, i int) (rune, bool) {
669		if i+4 > len(b) {
670			return 0, false
671		}
672		var v rune
673		for k := 0; k < 4; k++ {
674			c := b[i+k]
675			var d byte
676			switch {
677			case '0' <= c && c <= '9':
678				d = c - '0'
679			case 'a' <= c && c <= 'f':
680				d = c - 'a' + 10
681			case 'A' <= c && c <= 'F':
682				d = c - 'A' + 10
683			default:
684				return 0, false
685			}
686			v = v*16 + rune(d)
687		}
688		return v, true
689	}
