1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件从命令行入口回归“课程开放状态字段显式写成 JSON null 属于记录内容
11	// 损坏”：
12	//   - 这样的文件无论用哪条子命令访问，都在读取阶段以退出码 2 结束，标准
13	//     输出不出现课程列表、学生核对报告或登记成功提示；
14	//   - 标准错误点名记录文件与课程编号，并说明课程开放状态为空；
15	//   - 问题课程尚未被要求引用、或本次只查看另一名学生，也同样拒绝，不能
16	//     跳过这门课继续办理；
17	//   - open/Open/OPEN 及 Unicode 转义写法、字段在课程对象中的位置都不影响
18	//     结果；
19	//   - 原文件逐字节保留，即使用户发出的是“恢复开放”或其他写入类命令，也
20	//     不能借该操作把状态补写成 false/true。
21	//
22	// 同时固定不属本次纠正的行为：false 是合法停开状态（停开课程仍可建立要求、
23	// 停开前修读仍可提交成绩），省略 open 与空列表的既有读取规则不变，课程
24	// 名称与免修依据里的普通文字“null”不受影响。
25	
26	// nullOpenRecord 是一份结构完整、引用齐全的记录：学生 s1 的要求 r1 指向
27	// 4 学分课程 c1，另有学生 s2 与开放课程 c2；只有 c1 的开放状态被显式写成
28	// null。nullKey 给出状态字段在文件中的写法（open/Open/OPEN/转义），keyAt
29	// >0 时把该字段放到课程对象最前。
30	func nullOpenRecord(nullKey string) string {
31		return "{\n" +
32			`  "version": 1,` + "\n" +
33			`  "courses": [` + "\n" +
34			`    {"id": "c1", "name": "数学", "credit": 4, "` + nullKey + `": null},` + "\n" +
35			`    {"id": "c2", "name": "物理", "credit": 3, "open": true}` + "\n" +
36			`  ],` + "\n" +
37			`  "students": [{"id": "s1"}, {"id": "s2"}],` + "\n" +
38			`  "requirements": [` + "\n" +
39			`    {"id": "r1", "student": "s1", "course": "c1"},` + "\n" +
40			`    {"id": "r2", "student": "s2", "course": "c2"}` + "\n" +
41			`  ],` + "\n" +
42			`  "enrollments": [` + "\n" +
43			`    {"id": "e1", "student": "s1", "req": "r1", "term": "2024春", "result": "enrolled"}` + "\n" +
44			`  ], "waivers": [], "nextResultSeq": 0` + "\n" +
45			"}\n"
46	}
47	
48	// TestCLINullCourseOpenRejectsEveryCommand 主场景：任何子命令访问含
49	// "open":null 课程的文件都退出码 2、stdout 为空、stderr 点名文件与课程、
50	// 原文件字节不变——包括查看另一名学生 s2、list-courses，以及恢复开放、
51	// 登记其他学生等写入类命令。
52	func TestCLINullCourseOpenRejectsEveryCommand(t *testing.T) {
53		content := nullOpenRecord("open")
54		commands := [][]string{
55			{"list-courses"},
56			{"check", "s1"},
57			{"show", "s1"},
58			// 本次只查看另一名学生：其要求指向完全合法的 c2，仍必须整份拒绝。
59			{"check", "s2"},
60			{"show", "s2"},
61			{"student", "s9"},
62			{"course", "c9", "化学", "2"},
63			{"req", "s2", "r9", "c2"},
64			{"enroll", "s1", "r1", "2024秋", "e9"},
65			{"pass", "s1", "e1"},
66			{"waiver", "s1", "r1", "w9", "新依据"},
67			// 即使用户明确要恢复开放，也必须先报文件错误，不能借该操作补写状态。
68			{"course-open", "c1"},
69			{"course-close", "c2"},
70		}
71		for _, args := range commands {
72			t.Run(strings.Join(args, "_"), func(t *testing.T) {
73				file := filepath.Join(t.TempDir(), "records.json")
74				if err := os.WriteFile(file, []byte(content), 0o600); err != nil {
75					t.Fatal(err)
76				}
77				out, errText, code := runCLI(t, file, args...)
78				if code != exitFile {
79					t.Fatalf("命令 %v 遇 open:null 应退出码 %d，code=%d out=%q err=%q",
80						args, exitFile, code, out, errText)
81				}
82				if out != "" {
83					t.Fatalf("命令 %v 不得输出课程列表/核对报告/登记成功，out=%q", args, out)
84				}
85				for _, want := range []string{file, "内容损坏", "c1", "开放状态为空"} {
86					if !strings.Contains(errText, want) {
87						t.Fatalf("命令 %v 的错误应包含 %q，err=%q", args, want, errText)
