1	package credit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// escapedUpperCreditKey 解码后为 "Credit"（首字母大写，其余转义）。
12	const escapedUpperCreditKey = "\"\\u0043\\u0072edit\""
13	
14	// TestLoadRejectsCaseInsensitiveFieldConflicts 同一 JSON 对象内两个字段名
15	// 只有大小写不同、却都会被现有读取功能识别为同一条记录字段时，整份文件
16	// 必须判为内容损坏：Load 报错（点名文件、规范字段名与冲突的两个原始
17	// 写法）、标记文件已存在，且原文件每个字节原样保留。字段顺序、是否相邻、
18	// 两个值是否相同都不影响结果；后一个值绝不能悄悄顶替前一个。
19	func TestLoadRejectsCaseInsensitiveFieldConflicts(t *testing.T) {
20		cases := map[string]struct {
21			content string
22			field   string // 规范字段名
23			first   string // 先出现的原始写法
24			second  string // 后出现的原始写法
25		}{
26			"课程学分大小写冲突_小写在前": {
27				`{"version":1,"courses":[` +
28					`{"id":"c1","name":"数学","credit":4,"Credit":9,"open":true}]}` + "\n",
29				"credit", "credit", "Credit",
30			},
31			"课程学分大小写冲突_大写在前": {
32				// 颠倒顺序也必须拒绝，不能按后出现的 4 读取。
33				`{"version":1,"courses":[` +
34					`{"id":"c1","name":"数学","Credit":4,"credit":9,"open":true}]}` + "\n",
35				"credit", "Credit", "credit",
36			},
37			"课程学分全大写与小写冲突": {
38				`{"version":1,"courses":[` +
39					`{"id":"c1","name":"数学","CREDIT":4,"credit":9,"open":true}]}` + "\n",
40				"credit", "CREDIT", "credit",
41			},
42			"课程编号大小写冲突": {
43				`{"version":1,"courses":[` +
44					`{"id":"c1","ID":"c2","name":"数学","credit":4,"open":true}]}` + "\n",
45				"id", "id", "ID",
46			},
47			"学生记录编号大小写冲突": {
48				`{"version":1,"students":[{"id":"s1","ID":"s2"}]}` + "\n",
49				"id", "id", "ID",
50			},
51			"要求记录学生字段大小写冲突": {
52				`{"version":1,"students":[{"id":"s1"}],"courses":[` +
53					`{"id":"c1","name":"数学","credit":4,"open":true}],"requirements":[` +
54					`{"id":"r1","student":"s1","STUDENT":"s1","course":"c1"}]}` + "\n",
55				"student", "student", "STUDENT",
56			},
57			"要求记录课程字段大小写冲突": {
58				`{"version":1,"students":[{"id":"s1"}],"courses":[` +
59					`{"id":"c1","name":"数学","credit":4,"open":true}],"requirements":[` +
60					`{"id":"r1","student":"s1","course":"c1","Course":"c1"}]}` + "\n",
61				"course", "course", "Course",
62			},
63			"修读记录学生字段大小写冲突": {
64				`{"version":1,"students":[{"id":"s1"},{"id":"s2"}],"enrollments":[` +
65					`{"id":"e1","student":"s1","Student":"s2","req":"r1",` +
66					`"term":"2024春","result":"enrolled"}]}` + "\n",
67				"student", "student", "Student",
68			},
69			"修读结果序号大小写冲突": {
70				`{"version":1,"students":[{"id":"s1"}],"enrollments":[` +
71					`{"id":"e1","student":"s1","req":"r1","term":"2024春",` +
72					`"result":"passed","resultSeq":1,"ResultSeq":2}],"nextResultSeq":2}` + "\n",
73				"resultSeq", "resultSeq", "ResultSeq",
74			},
75			"免修状态大小写冲突": {
76				`{"version":1,"students":[{"id":"s1"}],"waivers":[` +
77					`{"id":"w1","student":"s1","req":"r1","basis":"竞赛获奖",` +
78					`"status":"rejected","STATUS":"approved"}]}` + "\n",
79				"status", "status", "STATUS",
80			},
81			"顶层courses与大写形式冲突_后者空数组": {
82				`{"version":1,"courses":[{"id":"c1","name":"数学","credit":4,"open":true}],` +
83					`"COURSES":[]}` + "\n",
84				"courses", "courses", "COURSES",
85			},
86			"顶层大写形式在前_小写后写空数组": {
87				`{"version":1,"COURSES":[{"id":"c1","name":"数学","credit":4,"open":true}],` +
88					`"courses":[],"students":[]}` + "\n",
89				"courses", "COURSES", "courses",
90			},
91			"顶层students大小写冲突": {
92				`{"version":1,"STUDENTS":[{"id":"s1"}],"students":[]}` + "\n",
93				"students", "STUDENTS", "students",
94			},
95			"冲突字段不相邻且两个值相同": {
96				`{"version":1,"courses":[` +
97					`{"credit":4,"id":"c1","name":"数学","open":true,"Credit":4}]}` + "\n",
98				"credit", "credit", "Credit",
99			},
100			"转义小写键与大写直接书写冲突": {
101				`{"version":1,"courses":[` +
102					`{"id":"c1","name":"数学",` + escapedCreditKey + `:4,"Credit":9,"open":true}]}` + "\n",
103				"credit", "credit", "Credit",
104			},
105			"转义大写键与小写直接书写冲突": {
106				`{"version":1,"courses":[` +
107					`{"id":"c1","name":"数学","credit":4,` + escapedUpperCreditKey + `:9,"open":true}]}` + "\n",
108				"credit", "credit", "Credit",
109			},
110			"大写顶层键数组内部记录冲突": {
111				// 顶层用 COURSES 承载课程列表，数组元素仍须按课程对象检查。
112				`{"version":1,"COURSES":[` +
113					`{"id":"c1","name":"数学","credit":4,"Credit":9,"open":true}]}` + "\n",
