118					`{"id":"c1","name":"数学","credit":4,"open":true},` +
119					`{"id":"c9","name":"无关课程","credit":1,"CREDIT":2,"open":true}],` +
120					`"students":[{"id":"s1"}],` +
121					`"requirements":[{"id":"r1","student":"s1","course":"c1"}],` +
122					`"enrollments":[{"id":"e1","student":"s1","req":"r1","term":"2024春",` +
123					`"result":"passed","resultSeq":1}],"waivers":[],"nextResultSeq":1}` + "\n",
124				"credit", "credit", "CREDIT",
